--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageCatballStarupSuccess.prefab
---@class OverseaManageCatBallStarUpSuccess
---@field Env                           	OverseaManageCatBallStarUpSuccess       
---@field controller                    	Engine.UI.UILuaDialog                   
---@field TextNumberAfterAttr2          	TMPro.TextMeshProUGUI                   
---@field TextNumberBeforeAttr2         	TMPro.TextMeshProUGUI                   
---@field TextNumberAfterAttr1          	TMPro.TextMeshProUGUI                   
---@field TextNumberBeforeAttr1         	TMPro.TextMeshProUGUI                   
---@field TextDesc                      	UnityEngine.UI.Text                     
---@field AfterStar                     	UnityEngine.RectTransform               
---@field BeforeStar                    	UnityEngine.RectTransform               
---@field TextName                      	UnityEngine.UI.Text                     
---@field ImgCatballIcon                	UnityEngine.UI.RawImage                 
local OverseaManageCatBallStarUpSuccess = Class('OverseaManageCatBallStarUpSuccess')

function OverseaManageCatBallStarUpSuccess:__init()

end

function OverseaManageCatBallStarUpSuccess:__delete()
    self.controller = nil
end

function OverseaManageCatBallStarUpSuccess:Awake()
    KTool.SetActive(self.ImgCatballIcon.gameObject, false)
end

function OverseaManageCatBallStarUpSuccess:OnDestroy()
    if self.__EventCaptureTextureCompleteAction then
        Events.RemoveListener(CatHouseCaptureTextureComplete, self.__EventCaptureTextureCompleteAction)
        self.__EventCaptureTextureCompleteAction = nil
    end
    self.controller = nil --删除lua层引⽤用到的c#对象
    self:Delete()
    self = nil
    
end

--region init

function OverseaManageCatBallStarUpSuccess:InitData(params)
    local parameters  = params
    local playerCatId = parameters.playerCatId
    local oldStar     = parameters.oldStar

    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    ---@type CatEggDojo
    local catEggDojo   = eggComponent:GetCat(playerCatId)
    ---@type MaidCoffeeCatRollConfigVo
    local vo           = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(catEggDojo.catId)
    local newStar = checkNumber(catEggDojo.star)

    local maxStar = MaidCoffeeUtils.CalcCatRollMaxStar()
    
    local skillId = vo.skillId
    ---@type MergeSkillTypeVo
    self._mergeVo = QuestConfMgr:GetInstance():GetMergeSkillTypeVo(skillId)
    ---@type MaidCoffeeCatRollSkillGrowVo
    local oldSkillGrowVo = MaidCoffeeUtils.GetMaidCoffeeCatRollSkillGrowVo(vo.skillId, oldStar)
    ---@type QuestUpBuffVo
    self._oldQuestBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(oldSkillGrowVo.skillNumId)
    ---@type MaidCoffeeCatRollSkillGrowVo
    local newSkillGrowVo = MaidCoffeeUtils.GetMaidCoffeeCatRollSkillGrowVo(vo.skillId, newStar)
    ---@type QuestUpBuffVo
    self._newQuestBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(newSkillGrowVo.skillNumId)
    -----@type AttrDefinesVo
    --self._attrDefinesVo = CardConfMgr:GetInstance():GetBasicAttrByBasicAttrAdditionId(self._oldQuestBuffVo.attributeId)

    local attributeType = self._oldQuestBuffVo.attributeType
    self._attributeType = attributeType
    
    ---@type MaidCoffeeCatRollStarVo
    self._newStarVo = MaidCoffeeUtils.GetMaidCoffeeCatRollStarVo(math.min(newStar, maxStar))
    local starVo       = MaidCoffeeUtils.GetMaidCoffeeCatRollStarVo(math.min(newStar + 1, maxStar))

    self._lvLimit = self._newStarVo.rank
    self._nextLvLimit = starVo.rank
    
    self._oldStar = oldStar
    self._newStar = newStar
    self._configVo = vo
    self._catEggDojo = catEggDojo
end

--endregion


--region logic

function OverseaManageCatBallStarUpSuccess:RefreshUI(params)
    --print(table.toString(params))
    self:InitData(params)
    self:RegEvent()
    self:FreshUI()
end

function OverseaManageCatBallStarUpSuccess:RegEvent()
    if self.__EventCaptureTextureCompleteAction then
        return
    end
    self.__EventCaptureTextureCompleteAction = Events.AddListener(CatHouseCaptureTextureComplete, Bind(self, self.OnEventCaptureTextureCompleteAction))
end


function OverseaManageCatBallStarUpSuccess:FreshUI()
    --- 刷新星级
    self:FreshStarGroup(self.BeforeStar, self._oldStar)
    self:FreshStarGroup(self.AfterStar,  self._newStar)
    
    self.TextName.text = self._configVo.name
    
    self.TextDesc.text = self._mergeVo.desc

    if self._attributeType == Constants.QuestUpBufAttributeType.Attribute then
        ---@type BasicAttrAdditionVo
        local additionVo                = CardConfMgr:GetInstance():GetBasicAttrAdditionById(self._oldQuestBuffVo.attributeId)
        local isConversion              = additionVo.isConversion
        self.TextNumberBeforeAttr1.text = attribute_format(isConversion, self._oldQuestBuffVo.addTypeNum)
        self.TextNumberAfterAttr1.text  = attribute_format(isConversion, self._newQuestBuffVo.addTypeNum)

    elseif self._attributeType == Constants.QuestUpBufAttributeType.CombatEffectivenessConst then
        self.TextNumberBeforeAttr1.text = self._oldQuestBuffVo.combatValue1
        self.TextNumberAfterAttr1.text  = self._newQuestBuffVo.combatValue1

    elseif self._attributeType == Constants.QuestUpBufAttributeType.CombatEffectivenessPercent then
        self.TextNumberBeforeAttr1.text = attribute_format(1, self._oldQuestBuffVo.combatValue2)
        self.TextNumberAfterAttr1.text  = attribute_format(1, self._newQuestBuffVo.combatValue2)

    end
    
    

    --- 刷新等级上限
    self.TextNumberBeforeAttr2.text = self._lvLimit
    self.TextNumberAfterAttr2.text  = self._nextLvLimit
    
    local configVo = self._configVo
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local fileNameId = eggComponent:GetFileNameId(MaidCoffeeConstants.BornType.Adult, configVo.catId, configVo.kind1)
    self._fileNameId = fileNameId
    eggComponent:CaptureTexture(MaidCoffeeConstants.BornType.Adult, checkNumber(configVo.catId), configVo.kind1,false, fileNameId)
    
end

function OverseaManageCatBallStarUpSuccess:FreshStarGroup(node, star)
    ---@type OverseaManageCatBallStarGroup
    local env = CfUtils.GetLuaScr(node, MaidCoffeeConstants.EnvPath.OverseaManageCatBallStarGroup)
    if not isNull(env) then
        env:FreshUI(star)
    end
end

--endregion


--region get/set

--endregion

--region handler

function OverseaManageCatBallStarUpSuccess:OnEventCaptureTextureCompleteAction(id, path)
    if self._fileNameId ~= id then return end
    print("OnEventCaptureTextureCompleteAction")
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local texture = eggComponent:LoadCaptureTexture(path, false)
    self.ImgCatballIcon.texture = texture
    KTool.SetActive(self.ImgCatballIcon.gameObject, true)
end
--endregion


return OverseaManageCatBallStarUpSuccess
 